const proxyquire: any = require("proxyquire").noCallThru().noPreserveCache();

describe("getTimezonesForCountry", () => {
  it("returns an empty array when a country has no timezones", () => {
    const { getTimezonesForCountry } = proxyquire(
      "../../../../../../../../../../../../subject_repositories/countries-and-timezones/src/index.js",
      {
        "./data.json": {
          countries: { XX: { id: "XX", name: "Test Country" } },
          timezones: {},
        },
        "./build-country": (_data: unknown, id: string) => ({
          id,
          name: "Test Country",
          timezones: undefined,
          allTimezones: undefined,
        }),
        "./build-timezone": (_data: unknown, name: string) => ({
          name,
          countries: [],
        }),
      }
    );

    expect(getTimezonesForCountry("XX")).toEqual([]);
  });
});
